Here's a complete example of data-driven MSTest tests using `[DataRow]` and `[DynamicData]`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace PriceCalculator.Tests;

[TestClass]
public class PriceCalculatorTests
{
    private Calculator.PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new Calculator.PriceCalculator();

    // --- DataRow: inline constant values ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double price, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)price);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 10, 90.00)]
    [DataRow(100.00, 0, 100.00)]
    [DataRow(50.00, 50, 25.00)]
    [DataRow(200.00, 100, 0.00)]
    public void ApplyDiscount_ReturnsExpected(double total, int discountPct, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, discountPct);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: complex/computed test cases ---

    [TestMethod]
    [DynamicData(nameof(CalculateTotalCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_DynamicCases(int quantity, decimal price, decimal expected)
    {
        var result = _calculator.CalculateTotal(quantity, price);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> CalculateTotalCases()
    {
        yield return new object[] { 1, 9.99m, 9.99m };
        yield return new object[] { 3, 15.00m, 45.00m };
        yield return new object[] { 10, 0.50m, 5.00m };
        yield return new object[] { 1000, 1.00m, 1000.00m };
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountEdgeCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_EdgeCases(decimal total, int discountPct, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPct);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> ApplyDiscountEdgeCases()
    {
        yield return new object[] { 0.01m, 10, 0.009m };
        yield return new object[] { 999.99m, 25, 749.9925m };
        yield return new object[] { 0m, 50, 0m };
    }

    // --- Negative cases ---

    [TestMethod]
    [DataRow(-1, 10.00)]
    [DataRow(1, -5.00)]
    public void CalculateTotal_InvalidInput_Throws(int quantity, double price)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(quantity, (decimal)price));
    }

    [TestMethod]
    [DataRow(100.00, -1)]
    [DataRow(100.00, 101)]
    public void ApplyDiscount_InvalidPercent_Throws(double total, int discountPct)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)total, discountPct));
    }
}
```

**Key practices shown:**

| Technique | When to use |
|-----------|-------------|
| `[DataRow]` | Simple inline constants (no `decimal` literals allowed, use `double` and cast) |
| `[DynamicData]` | Complex types, computed values, or `decimal` precision needed directly |
| `DynamicDataSourceType.Method` | Preferred over `Property` for lazy evaluation via `yield return` |

**Notes:**
- `[DataRow]` only supports compile-time constants — use `double` and cast to `decimal` in the method body.
- `[DynamicData]` methods must be `static` and return `IEnumerable<object[]>`.
- Each `object[]` maps positionally to the test method parameters.
- Separate positive/boundary tests from negative (exception) tests for clarity.
